def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find regularly spaced separator rows and columns: each is nearly uniform.
    def lines(axis):
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        found = []
        for i in range(n):
            vals = [grid[i][j] if axis == 0 else grid[j][i] for j in range(m)]
            if len(set(vals)) <= 2 and max(vals.count(v) for v in set(vals)) >= m - 2:
                found.append(i)
        return found

    rr, cc = lines(0), lines(1)

    def regular_groups(indices):
        # Retain the repeated regularly-spaced stripe positions.
        if len(indices) < 2:
            return indices
        gaps = [b-a for a,b in zip(indices, indices[1:])]
        step = max(set(gaps), key=gaps.count)
        return [i for i in indices if i == indices[0] or
                (i - indices[0]) % step == 0]

    rr, cc = regular_groups(rr), regular_groups(cc)
    if len(rr) < 2 or len(cc) < 2:
        return [[0]]

    out = []
    for a, b in zip(rr, rr[1:]):
        row = []
        for c, d in zip(cc, cc[1:]):
            counts = {}
            for y in range(a+1, b):
                for x in range(c+1, d):
                    v = grid[y][x]
                    counts[v] = counts.get(v, 0) + 1
            row.append(max(counts, key=counts.get) if counts else grid[a][c])
        out.append(row)
    return out
