def transform(grid):
    h, w = len(grid), len(grid[0])

    # The regular stripe spacing is the period of the repeated background.
    # Sample the colored intersections of the horizontal and vertical stripes.
    def period(lines):
        diffs = [b - a for a, b in zip(lines, lines[1:])]
        if not diffs:
            return 1
        return max(set(diffs), key=diffs.count)

    # Stripe rows/columns have a repeated color across most of their length;
    # patterned background rows/columns do not.
    stripe_rows = []
    for r in range(h):
        if max(grid[r].count(v) for v in set(grid[r])) >= w - 2:
            stripe_rows.append(r)
    stripe_cols = []
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if max(vals.count(v) for v in set(vals)) >= h - 2:
            stripe_cols.append(c)

    # For grids where the stripes alternate with a dominant background, use
    # their observed periodic positions.
    def spaced(indices):
        if len(indices) < 2:
            return indices
        p = period(indices)
        return [i for i in indices if (i - indices[0]) % p == 0]

    stripe_rows = spaced(stripe_rows)
    stripe_cols = spaced(stripe_cols)

    if not stripe_rows or not stripe_cols:
        return [[grid[0][0]]]
    return [[grid[r][c] for c in stripe_cols] for r in stripe_rows]
