def transform(grid):
    # Sample the colored crossings of the regularly spaced grid lines,
    # omitting the last line, which is the outer boundary.
    h, w = len(grid), len(grid[0])

    def stripe_rows():
        return [r for r in range(h)
                if len(set(grid[r])) <= 2 and max(grid[r].count(v) for v in set(grid[r])) >= w - 2]

    def stripe_cols():
        out = []
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) <= 2 and max(vals.count(v) for v in set(vals)) >= h - 2:
                out.append(c)
        return out

    def regular(xs):
        if len(xs) < 2:
            return xs
        from collections import Counter
        step = Counter(b-a for a, b in zip(xs, xs[1:])).most_common(1)[0][0]
        return [x for x in xs if (x-xs[0]) % step == 0]

    rs, cs = regular(stripe_rows()), regular(stripe_cols())
    return [[grid[r][c] for c in cs[:-1]] for r in rs[:-1]]
